ource_sha256":"13492a765bec0b00426851997d335ea5948f8171a6affd108f150a4a4cc6103f"}],"fact_id":"F_SIM_DESIGN","kind":"source_fact","statement":"The simulation notebook cell 4 specifies n in [50,100,150], p=5, q=10, noise=1 and Gaussian structural draws. Its beta-first then Theta in-place order is equivalent to frozen-old-state updates: the beta step reads old Theta, and the Theta step does not depend on beta."},{"allowed_stages":[],"discloses_target_contribution":true,"evidence":[{"locator":"Notebook cell 4, num_simulations, aggregation and commented rate statements","source_id":"iv-simulation","source_sha256":"13492a765bec0b00426851997d335ea5948f8171a6affd108f150a4a4cc6103f"}],"fact_id":"S_NOTEBOOK","kind":"source_result","statement":"Notebook cell 4 sets 100 simulations and averages GD errors; it does not provide independent per-run records in this source representation, and commented rate lines do not establish execution."},{"allowed_stages":["EXP"],"discloses_target_contribution":false,"evidence":[],"fact_id":"M_SCOPE","kind":"maintainer_scope","statement":"Requested candidate is a finite-sample CPU numerical EXP only; Transformer/GPU and whole-paper claims are outside its scope."},{"allowed_stages":[],"discloses_target_contribution":false,"evidence":[{"locator":"arXiv v1 version metadata; does not establish first disclosure","source_id":"iv-abstract-v1","source_sha256":"be8bd6c83856a22f292a3b3fa476bba525d648d4a2ccba7943b296f363af58bb"}],"fact_id":"U_DISCLOSURE","kind":"unknown","statement":"First-disclosure date and historical literature/library coverage and read-access disclosure are unverified."},{"allowed_stages":[],"discloses_target_contribution":false,"evidence":[{"locator":"Repository LICENSE, full text","source_id":"iv-license","source_sha256":"0c62244358639b87361d70abf720d79cabb5c4e40a114cb933e1a164d82e513b"}],"fact_id":"M_RIGHTS","kind":"maintainer_scope","statement":"Repository MIT license is recorded as provenance; scope over paper and newly authored assets is not asserted and public release rights review remains pending."}],"paper_id":"iclr2025-QfhU3ZC2g1","schema_version":"material-package-1","status":"candidate","tasks":[{"assets":[{"path":"assets/task.md","sha256":"d716cfa74056e21574bdbcdd377b5456d8242bf9db8ab4e84110329d5fd1f021","visibility":"public"},{"path":"assets/base_resources.py","sha256":"c720367a63675508b59ad9cd066768e4d958cf9a97f9ce13982201af64067ea2","visibility":"public"},{"path":"assets/NOTICE.txt","sha256":"3c39fa64e74e782f92f77912ae1e60c352f53a014f0a0625289f78dc86f2690d","visibility":"public"}],"input_contract":{"description":"Offline CPU experiment using the public self-contained equation/method specification and starter resources; no target implementation or author experimental conclusion is supplied.","files":[{"path":"assets/task.md","sha256":"d716cfa74056e21574bdbcdd377b5456d8242bf9db8ab4e84110329d5fd1f021","visibility":"public"},{"path":"assets/base_resources.py","sha256":"c720367a63675508b59ad9cd066768e4d958cf9a97f9ce13982201af64067ea2","visibility":"public"},{"path":"assets/NOTICE.txt","sha256":"3c39fa64e74e782f92f77912ae1e60c352f53a014f0a0625289f78dc86f2690d","visibility":"public"}],"resources":{"cpus":2,"disk_mb":1024,"memory_mb":2048,"rationale":"Moderate n×q and n×p arrays and repeated NumPy least-squares/gradient trajectories; selected repeat counts and rate settings must fit this budget.","wall_seconds":1200}},"input_fact_ids":["F_MODEL","F_ASSUMPTIONS","F_2SLS","F_SIM_DESIGN","M_SCOPE","F_UPDATES"],"output_contract":{"files":["experiment.py","config.json","replicate_results.jsonl","report.json"],"format":"Strict machine-readable JSON and JSONL per assets/task.md; retain per-replicate and per-iteration evidence, config linkage, aggregates and hypothesis evidence links."},"paper_id":"iclr2025-QfhU3ZC2g1","private_fact_ids":["S_NOTEBOOK","U_DISCLOSURE","M_RIGHTS"],"private_source_ids":["iv-paper-v1","iv-simulation","iv-abstract-v1","iv-license"],"split":"development","task_id":"iv-c