\boldsymbol{\\mathcal{E}}_{2}\\right\\|\\\\ &\\leq B_{\\Theta}+\\left\\|\\left(\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}\\right)^{-1}\\boldsymbol{Z}^{\\top}\\boldsymbol{\\mathcal{E}}_{2}\\right\\|\\\\ &\\leq B_{\\Theta}+\\frac{\\delta_{z\\epsilon_{2}}}{\\lambda_{z}}:=B_{\\hat{\\Theta}}.\\end{split}$ (22) With Lemma A.3 (Remark A.1 ), combining (20 )(22 ), we have: $\\displaystyle\\begin{split}\\mathbb{P}\\left\\{\\left\\|\\frac{1}{n}\\boldsymbol{X}^{\\top}\\boldsymbol{Z}(\\boldsymbol{Z}^{\\top}\\boldsymbol{Z})^{-1}\\boldsymbol{Z}^{\\top}\\boldsymbol{\\mathcal{E}}_{1}-\\boldsymbol{0}\\right\\|\\geq\\varepsilon\\middle|\\mathcal{A}\\right\\}&\\leq(q+1)\\exp\\left(-\\frac{n^{2}(\\frac{\\varepsilon}{B_{\\hat{\\Theta}}})^{2}/2}{\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})+B_{z\\epsilon_{1}}n(\\frac{\\varepsilon}{B_{\\hat{\\Theta}}})/3}\\right)\\\\ &=(q+1)\\exp\\left(-\\frac{n^{2}\\varepsilon^{2}/2}{B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})+B_{\\hat{\\Theta}}B_{z\\epsilon_{1}}n\\varepsilon/3}\\right).\\end{split}$ (23) Additionally, with Lemma A.3 , combining (19 )(21 ), we have: $\\displaystyle\\begin{split}&\\mathbb{P}\\left\\{\\left\\|\\frac{1}{n}\\boldsymbol{X}^{\\top}\\boldsymbol{Z}(\\boldsymbol{Z}^{\\top}\\boldsymbol{Z})^{-1}\\boldsymbol{Z}^{\\top}\\boldsymbol{X}-\\boldsymbol{Q}_{zx}^{\\top}\\boldsymbol{Q}_{zz}^{-1}\\boldsymbol{Q}_{zx}\\right\\|\\geq\\varepsilon\\middle|\\mathcal{A}\\right\\}\\\\ &\\leq 2(p+q)\\exp\\left(-\\frac{n^{2}(\\frac{\\lambda_{z}\\varepsilon}{3B_{zx}})^{2}/2}{\\nu(\\bar{\\boldsymbol{\\Omega}}_{zx}|\\mathcal{A})+\\bar{B}_{zx}n(\\frac{\\lambda_{z}\\varepsilon}{3B_{zx}})/3}\\right)+2q\\exp\\left(-\\frac{\\lambda_{z}^{4}n^{2}(\\frac{\\varepsilon}{3B_{zx}^{2}})^{2}/2}{\\nu(\\bar{\\boldsymbol{\\Omega}}_{zz}|\\mathcal{A})+\\lambda_{z}^{2}\\bar{B}_{zz}n(\\frac{\\varepsilon}{3B_{zx}^{2}})/3}\\right)\\\\ &=2(p+q)\\exp\\left(-\\frac{\\lambda_{z}^{2}n^{2}\\varepsilon^{2}/2}{9B_{zx}^{2}\\nu(\\bar{\\boldsymbol{\\Omega}}_{zx}|\\mathcal{A})+\\lambda_{z}B_{zx}\\bar{B}_{zx}n\\varepsilon}\\right)+2q\\exp\\left(-\\frac{\\lambda_{z}^{4}n^{2}\\varepsilon^{2}/2}{9B_{zx}^{4}\\nu(\\bar{\\boldsymbol{\\Omega}}_{zz}|\\mathcal{A})+\\lambda_{z}^{2}B_{zx}^{2}\\bar{B}_{zz}n\\varepsilon}\\right).\\end{split}$ Applying Lemma A.2 again, we have: $\\displaystyle\\begin{split}&\\mathbb{P}\\left\\{\\left\\|n\\left(\\boldsymbol{X}^{\\top}\\boldsymbol{Z}(\\boldsymbol{Z}^{\\top}\\boldsymbol{Z})^{-1}\\boldsymbol{Z}^{\\top}\\boldsymbol{X}\\right)^{-1}-(\\boldsymbol{Q}_{ZX}^{\\top}\\boldsymbol{Q}_{zz}^{-1}\\boldsymbol{Q}_{zx})^{-1}\\right\\|\\geq\\varepsilon\\middle|\\mathcal{A}\\right\\}\\\\ &\\leq 2(p+q)\\exp\\left(-\\frac{\\lambda_{z}^{2}n^{2}(\\lambda_{\\tilde{x}}^{2}\\varepsilon)^{2}/2}{9B_{zx}^{2}\\nu(\\bar{\\boldsymbol{\\Omega}}_{zx}|\\mathcal{A})+\\lambda_{z}B_{zx}\\bar{B}_{zx}n(\\lambda_{\\tilde{x}}^{2}\\varepsilon)}\\right)+2q\\exp\\left(-\\frac{\\lambda_{z}^{4}n^{2}(\\lambda_{\\tilde{x}}^{2}\\varepsilon)^{2}/2}{9B_{zx}^{4}\\nu(\\bar{\\boldsymbol{\\Omega}}_{zz}|\\mathcal{A})+\\lambda_{z}^{2}B_{zx}^{2}\\bar{B}_{zz}n(\\lambda_{\\tilde{x}}^{2}\\varepsilon)}\\right)\\\\ &=2(p+q)\\exp\\left(-\\frac{\\lambda_{z}^{2}\\lambda_{\\tilde{x}}^{4}n^{2}\\varepsilon^{2}/2}{9B_{zx}^{2}\\nu(\\bar{\\boldsymbol{\\Omega}}_{zx}|\\mathcal{A})+\\lambda_{z}\\lambda_{\\tilde{x}}^{2}B_{zx}\\bar{B}_{zx}n\\varepsilon}\\right)+2q\\exp\\left(-\\frac{\\lambda_{z}^{4}\\lambda_{\\tilde{x}}^{4}n^{2}\\varepsilon^{2}/2}{9B_{zx}^{4}\\nu(\\bar{\\boldsymbol{\\Omega}}_{zz}|\\mathcal{A})+\\lambda_{z}^{2}\\lambda_{\\tilde{x}}^{2}B_{zx}^{2}\\bar{B}_{zz}n\\varepsilon}\\right).\\end{split}$ (24)"},{"child_ids":["A1.Ex27"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A1.EGx56","tag":"table","text":"$\\displaystyle n\\left(\\boldsymbol{X}^{\\top}\\boldsymbol{Z}(\\boldsymbol{Z}^{\\top}\\boldsymbol{Z})^{-1}\\boldsymbol{Z}^{\\top}\\boldsymbol{X}\\right)^{-1}\\overset{\\textsf{p}}{\\rightarrow}(\\boldsymbol{Q}_{ZX}^{\\top}\\boldsymbol{Q}_{zz}^{-1}\\boldsymbol{Q}_{zx})^{-1}.$"},{"child_ids":["A1.Ex28","A1.Ex29","A1.Ex30","A1.Ex31"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A1.EGx57","tag":"table","text":"$\\displaystyle\\mathbb{P}\\left\\{\\left\\|\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}-\\boldsymbol{\\beta}\\right\\|\\geq\\varepsilon\\middle|\\mathcal{A}\\right\\}$ $\\displaystyle=\\mathbb{P}\\left\\{\\left\\|\\left(\\boldsymbol{X}^{\\top}\\boldsymbol{Z}(\\boldsymbol{Z}^{\\top}\\boldsymbol{Z})^{-1}\\boldsymbol{Z}^{\\top}\\boldsymbol{X}\\right)^{-1}\\boldsymbol{X}^{\\top}\\boldsymbol{Z}(\\boldsymbol{Z}^{\\top}\\boldsymbol{Z})^{-1}\\boldsymbol{Z}^{\\top}\\boldsymbol{\\mathcal{E}}_{1}-\\boldsymbol{0}\\right\\|\\geq\\varepsilon\\middle|\\mathcal{A}\\right\\}$ $\\displaystyle\\leq(q+1)\\exp\\left(-\\frac{n^{2}(\\lambda_{\\tilde{x}}\\varepsilon)^{2}/2}{B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})+B_{\\hat{\\Theta}}B_{z\\epsilon_{1}}n(\\lambda_{\\tilde{x}}\\varepsilon)/3}\\right)$ $\\displaystyle=(q+1)\\exp\\left(-\\frac{\\lambda_{\\tilde{x}}^{2}n^{2}\\varepsilon^{2}/2}{B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})+\\lambda_{\\tilde{x}}B_{\\hat{\\Theta}}B_{z\\epsilon_{1}}n\\varepsilon/3}\\right).$"},{"child_ids":["A1.SS1.p9.1","A1.SS1.p9.1.1","A1.EGx56","A1.Ex27","A1.SS1.p9.2","A1.SS1.p9.2.1","A1.EGx57","A1.Ex28","A1.Ex29","A1.Ex30","A1.Ex31"],"classes":["ltx_para","ltx_noindent"],"id":"A1.SS1.p9","tag":"div","text":"Therefore, we have shown that under event $\\mathcal{A}$ , $\\displaystyle n\\left(\\boldsymbol{X}^{\\top}\\boldsymbol{Z}(\\boldsymbol{Z}^{\\top}\\boldsymbol{Z})^{-1}\\boldsymbol{Z}^{\\top}\\boldsymbol{X}\\right)^{-1}\\overset{\\textsf{p}}{\\rightarrow}(\\boldsymbol{Q}_{ZX}^{\\top}\\boldsymbol{Q}_{zz}^{-1}\\boldsymbol{Q}_{zx})^{-1}.$ From equation (17 ), combining (23 ) and (24 ) with Lemma A.3 (Remark A.1 ), we have: $\\displaystyle\\mathbb{P}\\left\\{\\left\\|\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}-\\boldsymbol{\\beta}\\right\\|\\geq\\varepsilon\\middle|\\mathcal{A}\\right\\}$ $\\displaystyle=\\mathbb{P}\\left\\{\\left\\|\\left(\\boldsymbol{X}^{\\top}\\boldsymbol{Z}(\\boldsymbol{Z}^{\\top}\\boldsymbol{Z})^{-1}\\boldsymbol{Z}^{\\top}\\boldsymbol{X}\\right)^{-1}\\boldsymbol{X}^{\\top}\\boldsymbol{Z}(\\boldsymbol{Z}^{\\top}\\boldsymbol{Z})^{-1}\\boldsymbol{Z}^{\\top}\\boldsymbol{\\mathcal{E}}_{1}-\\boldsymbol{0}\\right\\|\\geq\\varepsilon\\middle|\\mathcal{A}\\right\\}$ $\\displaystyle\\leq(q+1)\\exp\\left(-\\frac{n^{2}(\\lambda_{\\tilde{x}}\\varepsilon)^{2}/2}{B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})+B_{\\hat{\\Theta}}B_{z\\epsilon_{1}}n(\\lambda_{\\tilde{x}}\\varepsilon)/3}\\right)$ $\\displaystyle=(q+1)\\exp\\left(-\\frac{\\lambda_{\\tilde{x}}^{2}n^{2}\\varepsilon^{2}/2}{B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})+\\lambda_{\\tilde{x}}B_{\\hat{\\Theta}}B_{z\\epsilon_{1}}n\\varepsilon/3}\\right).$"},{"child_ids":["A1.E25"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A1.EGx58","tag":"table","text":"$\\displaystyle\\begin{split}&\\mathbb{E}\\left[\\|\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta}\\|^{2}\\right]\\\\ &=\\mathbb{E}\\left[\\|\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta}\\|^{2}\\middle|\\mathcal{A}\\right]\\mathbb{P}\\left\\{\\mathcal{A}\\right\\}+\\mathbb{E}\\left[\\|\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta}\\|^{2}\\middle|\\mathcal{A}^{c}\\right]\\mathbb{P}\\left\\{\\mathcal{A}^{c}\\right\\}\\\\ &\\leq\\mathbb{E}\\left[\\|\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}-\\boldsymbol{\\beta}\\|^{2}\\middle|\\mathcal{A}\\right]\\mathbb{P}\\left\\{\\mathcal{A}\\right\\}+\\mathbb{E}\\left[\\|\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta}\\|^{2}\\middle|\\mathcal{A}^{c}\\right]\\mathbb{P}\\left\\{\\mathcal{A}^{c}\\right\\}\\\\ &\\leq\\mathbb{E}\\left[\\|\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}-\\boldsymbol{\\beta}\\|^{2}\\middle|\\mathcal{A}\\right]+\\mathbb{E}\\left[\\|\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta}\\|^{2}\\middle|\\mathcal{A}^{c}\\right]\\cdot\\xi,\\end{split}$ (25)"},{"child_ids":["A1.E26"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A1.EGx59","tag":"table","text":"$\\displaystyle\\mathbb{E}\\left[\\|\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta}\\|^{2}\\middle|\\mathcal{A}^{c}\\right]\\leq 4B_{\\beta}^{2},$ (26)"},{"child_ids":["A1.E27"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A1.EGx60","tag":"table","text":"$\\displaystyle\\begin{split}&\\mathbb{E}\\left[\\|\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}-\\boldsymbol{\\beta}\\|^{2}\\middle|\\mathcal{A}\\right]\\\\ &=\\int_{0}^{\\infty}\\mathbb{P}\\left\\{\\|\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}-\\boldsymbol{\\beta}\\|^{2}\\geq\\varepsilon\\middle|\\mathcal{A}\\right\\}d\\varepsilon\\\\ &=\\int_{0}^{\\infty}\\mathbb{P}\\left\\{\\|\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}-\\boldsymbol{\\beta}\\|\\geq\\sqrt{\\varepsilon}\\middle|\\mathcal{A}\\right\\}d\\varepsilon\\\\ &\\leq\\int_{0}^{\\infty}(q+1)\\exp\\left(-\\frac{\\lambda_{\\tilde{x}}^{2}n^{2}\\varepsilon/2}{B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})+\\lambda_{\\tilde{x}}B_{\\hat{\\Theta}}B_{z\\epsilon_{1}}n\\sqrt{\\varepsilon}/3}\\right)d\\varepsilon\\\\ &\\leq(q+1)\\left[\\int_{0}^{c}\\exp\\left(-\\frac{\\lambda_{\\tilde{x}}^{2}n^{2}\\varepsilon/2}{2B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}\\right)d\\varepsilon+\\int_{c}^{\\infty}\\exp\\left(-\\frac{\\lambda_{\\tilde{x}}n\\sqrt{\\varepsilon}/2}{2B_{\\hat{\\Theta}}B_{z\\epsilon_{1}}/3}\\right)d\\varepsilon\\right]\\\\ &=(q+1)\\left[\\frac{4B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{\\lambda_{\\tilde{x}}^{2}n^{2}}\\left(1-\\exp\\left(-\\frac{9\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{4B_{z\\epsilon_{1}}^{2}}\\right)\\right)+\\left(\\frac{8B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{\\lambda_{\\tilde{x}}^{2}n^{2}}+\\frac{32B_{\\hat{\\Theta}}^{2}B_{z\\epsilon_{1}}^{2}}{9\\lambda_{\\tilde{x}}^{2}n^{2}}\\right)\\exp\\left(-\\frac{9\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{4B_{z\\epsilon_{1}}^{2}}\\right)\\right]\\\\ &\\leq(q+1)\\left[\\frac{4B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{\\lambda_{\\tilde{x}}^{2}n^{2}}+\\frac{8B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{\\lambda_{\\tilde{x}}^{2}n^{2}}+\\frac{32B_{\\hat{\\Theta}}^{2}B_{z\\epsilon_{1}}^{2}}{9\\lambda_{\\tilde{x}}^{2}n^{2}}\\right]\\\\ &=\\frac{(q+1)B_{\\hat{\\Theta}}^{2}}{\\lambda_{\\tilde{x}}^{2}n^{2}}\\left[12\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})+\\frac{32B_{z}^{2}B_{\\epsilon_{1}}^{2}}{9}\\right].\\end{split}$ (27)"},{"child_ids":["A1.SS1.p10.1","A1.SS1.p10.1.1","A1.EGx58","A1.E25","A1.SS1.p10.2","A1.SS1.p10.2.1","A1.EGx59","A1.E26","A1.SS1.p10.3","A1.SS1.p10.3.1","A1.EGx60","A1.E27"],"classes":["ltx_para","ltx_noindent"],"id":"A1.SS1.p10","tag":"div","text":"For the second part of the theorem, let $c:=\\left(\\frac{3B_{\\hat{\\Theta}}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{\\lambda_{\\tilde{x}}B_{z\\epsilon_{1}}n}\\right)^{2}$ , we have: $\\displaystyle\\begin{split}&\\mathbb{E}\\left[\\|\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta}\\|^{2}\\right]\\\\ &=\\mathbb{E}\\left[\\|\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta}\\|^{2}\\middle|\\mathcal{A}\\right]\\mathbb{P}\\lef