_{\\tilde{x}}^{2}n^{2}\\varepsilon/2}{2B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}\\right)d\\varepsilon+\\int_{c}^{\\infty}\\exp\\left(-\\frac{\\lambda_{\\tilde{x}}n\\sqrt{\\varepsilon}/2}{2B_{\\hat{\\Theta}}B_{z\\epsilon_{1}}/3}\\right)d\\varepsilon\\right]\\\\ &=(q+1)\\left[\\frac{4B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{\\lambda_{\\tilde{x}}^{2}n^{2}}\\left(1-\\exp\\left(-\\frac{9\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{4B_{z\\epsilon_{1}}^{2}}\\right)\\right)+\\left(\\frac{8B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{\\lambda_{\\tilde{x}}^{2}n^{2}}+\\frac{32B_{\\hat{\\Theta}}^{2}B_{z\\epsilon_{1}}^{2}}{9\\lambda_{\\tilde{x}}^{2}n^{2}}\\right)\\exp\\left(-\\frac{9\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{4B_{z\\epsilon_{1}}^{2}}\\right)\\right]\\\\ &\\leq(q+1)\\left[\\frac{4B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{\\lambda_{\\tilde{x}}^{2}n^{2}}+\\frac{8B_{\\hat{\\Theta}}^{2}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})}{\\lambda_{\\tilde{x}}^{2}n^{2}}+\\frac{32B_{\\hat{\\Theta}}^{2}B_{z\\epsilon_{1}}^{2}}{9\\lambda_{\\tilde{x}}^{2}n^{2}}\\right]\\\\ &=\\frac{(q+1)B_{\\hat{\\Theta}}^{2}}{\\lambda_{\\tilde{x}}^{2}n^{2}}\\left[12\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})+\\frac{32B_{z}^{2}B_{\\epsilon_{1}}^{2}}{9}\\right].\\end{split}$ (27)"},{"child_ids":["A1.E28"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A1.EGx61","tag":"table","text":"$\\displaystyle\\begin{split}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})&=\\max\\left\\{\\bigg\\|\\mathbb{E}\\Big[\\Big(\\sum_{i=1}^{n}\\boldsymbol{z}_{i}\\epsilon_{1,i}\\Big)^{\\top}\\Big(\\sum_{j=1}^{n}\\boldsymbol{z}_{j}\\epsilon_{1,j}\\Big)\\Big|\\mathcal{A}\\Big]\\bigg\\|,\\bigg\\|\\mathbb{E}\\Big[\\Big(\\sum_{i=1}^{n}\\boldsymbol{z}_{i}\\epsilon_{1,i}\\Big)\\Big(\\sum_{j=1}^{n}\\boldsymbol{z}_{j}\\epsilon_{1,j}\\Big)^{\\top}\\Big|\\mathcal{A}\\Big]\\bigg\\|\\right\\}\\\\ &=\\max\\left\\{\\bigg\\|\\mathbb{E}\\Big[\\sum_{i=1}^{n}\\epsilon_{1,i}^{2}\\boldsymbol{z}_{i}^{\\top}\\boldsymbol{z}_{i}\\Big|\\mathcal{A}\\Big]\\bigg\\|,\\bigg\\|\\mathbb{E}\\bigg[\\sum_{i=1}^{n}\\epsilon_{1,i}^{2}\\boldsymbol{z}_{i}\\boldsymbol{z}_{i}^{\\top}\\Big|\\mathcal{A}\\Big]\\bigg\\|\\right\\}\\\\ &\\leq\\mathcal{O}(nB_{z}^{2}\\sigma_{1}^{2}).\\end{split}$ (28)"},{"child_ids":["A1.SS1.p11.1","A1.SS1.p11.1.1","A1.EGx61","A1.E28","A1.SS1.p11.2","A1.SS1.p11.2.1"],"classes":["ltx_para"],"id":"A1.SS1.p11","tag":"div","text":"Note that we further have the following bound: $\\displaystyle\\begin{split}\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{1}}|\\mathcal{A})&=\\max\\left\\{\\bigg\\|\\mathbb{E}\\Big[\\Big(\\sum_{i=1}^{n}\\boldsymbol{z}_{i}\\epsilon_{1,i}\\Big)^{\\top}\\Big(\\sum_{j=1}^{n}\\boldsymbol{z}_{j}\\epsilon_{1,j}\\Big)\\Big|\\mathcal{A}\\Big]\\bigg\\|,\\bigg\\|\\mathbb{E}\\Big[\\Big(\\sum_{i=1}^{n}\\boldsymbol{z}_{i}\\epsilon_{1,i}\\Big)\\Big(\\sum_{j=1}^{n}\\boldsymbol{z}_{j}\\epsilon_{1,j}\\Big)^{\\top}\\Big|\\mathcal{A}\\Big]\\bigg\\|\\right\\}\\\\ &=\\max\\left\\{\\bigg\\|\\mathbb{E}\\Big[\\sum_{i=1}^{n}\\epsilon_{1,i}^{2}\\boldsymbol{z}_{i}^{\\top}\\boldsymbol{z}_{i}\\Big|\\mathcal{A}\\Big]\\bigg\\|,\\bigg\\|\\mathbb{E}\\bigg[\\sum_{i=1}^{n}\\epsilon_{1,i}^{2}\\boldsymbol{z}_{i}\\boldsymbol{z}_{i}^{\\top}\\Big|\\mathcal{A}\\Big]\\bigg\\|\\right\\}\\\\ &\\leq\\mathcal{O}(nB_{z}^{2}\\sigma_{1}^{2}).\\end{split}$ (28) Plugging (26 )(27 )(28 ) into (25 ) completes the proof. ∎"},{"child_ids":["A2.Ex32"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx62","tag":"table","text":"$\\displaystyle\\left\\|\\boldsymbol{\\Omega}^{(t)}\\right\\|_{F}\\leq cr^{t}.$"},{"child_ids":["A2.Ex33"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx63","tag":"table","text":"$\\displaystyle T_{0}=\\left\\lceil\\log_{r}\\frac{(1-r)(\\varepsilon/d)}{c\\left(1+(1-r)(\\varepsilon/d)\\right)}\\right\\rceil,$"},{"child_ids":["A2.Ex34"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx64","tag":"table","text":"$\\displaystyle\\left\\|\\prod_{t=T_{0}}^{\\infty}(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t)})-\\boldsymbol{I}\\right\\|_{F}<\\varepsilon,$"},{"child_ids":["A2.Ex35"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx65","tag":"table","text":"$\\displaystyle\\left\\|\\prod_{t=T_{0}}^{\\infty}(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t)})\\right\\|_{F}<\\sqrt{d}+\\varepsilon.$"},{"child_ids":["A2.Thmlemma1.p1.1","A2.EGx62","A2.Ex32","A2.Thmlemma1.p1.2","A2.EGx63","A2.Ex33","A2.Thmlemma1.p1.3","A2.EGx64","A2.Ex34","A2.Thmlemma1.p1.4","A2.EGx65","A2.Ex35"],"classes":["ltx_para"],"id":"A2.Thmlemma1.p1","tag":"div","text":"Suppose $\\{\\boldsymbol{\\Omega}^{(1)},\\ldots,\\boldsymbol{\\Omega}^{(t)},\\ldots\\}$ is a $d\\times d$ -matrix sequence decaying with exponential rate $r$ , i.e. for some constant $c>0$ and $0<r<1$ , $\\displaystyle\\left\\|\\boldsymbol{\\Omega}^{(t)}\\right\\|_{F}\\leq cr^{t}.$ Then for any $\\varepsilon>0$ , there exists a finite constant: $\\displaystyle T_{0}=\\left\\lceil\\log_{r}\\frac{(1-r)(\\varepsilon/d)}{c\\left(1+(1-r)(\\varepsilon/d)\\right)}\\right\\rceil,$ such that $\\displaystyle\\left\\|\\prod_{t=T_{0}}^{\\infty}(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t)})-\\boldsymbol{I}\\right\\|_{F}<\\varepsilon,$ and hence $\\displaystyle\\left\\|\\prod_{t=T_{0}}^{\\infty}(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t)})\\right\\|_{F}<\\sqrt{d}+\\varepsilon.$"},{"child_ids":["A2.Thmlemma1.2","A2.Thmlemma1.3","A2.Thmlemma1.p1","A2.Thmlemma1.p1.1","A2.EGx62","A2.Ex32","A2.Thmlemma1.p1.2","A2.EGx63","A2.Ex33","A2.Thmlemma1.p1.3","A2.EGx64","A2.Ex34","A2.Thmlemma1.p1.4","A2.EGx65","A2.Ex35"],"classes":["ltx_theorem","ltx_theorem_lemma"],"id":"A2.Thmlemma1","tag":"div","text":"Lemma B.1 . Suppose $\\{\\boldsymbol{\\Omega}^{(1)},\\ldots,\\boldsymbol{\\Omega}^{(t)},\\ldots\\}$ is a $d\\times d$ -matrix sequence decaying with exponential rate $r$ , i.e. for some constant $c>0$ and $0<r<1$ , $\\displaystyle\\left\\|\\boldsymbol{\\Omega}^{(t)}\\right\\|_{F}\\leq cr^{t}.$ Then for any $\\varepsilon>0$ , there exists a finite constant: $\\displaystyle T_{0}=\\left\\lceil\\log_{r}\\frac{(1-r)(\\varepsilon/d)}{c\\left(1+(1-r)(\\varepsilon/d)\\right)}\\right\\rceil,$ such that $\\displaystyle\\left\\|\\prod_{t=T_{0}}^{\\infty}(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t)})-\\boldsymbol{I}\\right\\|_{F}<\\varepsilon,$ and hence $\\displaystyle\\left\\|\\prod_{t=T_{0}}^{\\infty}(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t)})\\right\\|_{F}<\\sqrt{d}+\\varepsilon.$"},{"child_ids":["A2.Ex36"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx66","tag":"table","text":"$\\displaystyle\\left\\|\\boldsymbol{\\Omega}^{(k)}\\right\\|_{F}=\\sqrt{\\sum_{i,j=1}^{p}\\boldsymbol{\\Omega}_{ij}^{(k)2}}\\leq cr^{k},$"},{"child_ids":["A2.Ex37"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx67","tag":"table","text":"$\\displaystyle\\left|\\boldsymbol{\\Omega}_{ij}^{(k)}\\right|\\leq cr^{k},\\quad\\forall i,j,k.$"},{"child_ids":["A2.Ex38"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx68","tag":"table","text":"$\\displaystyle\\left\\|\\boldsymbol{\\Omega}^{(k)}\\boldsymbol{\\Omega}^{(l)}\\right\\|_{F}\\leq\\left\\|\\boldsymbol{\\Omega}^{(k)}\\right\\|_{F}\\left\\|\\boldsymbol{\\Omega}^{(l)}\\right\\|_{F}\\leq c^{2}r^{k+l},$"},{"child_ids":["A2.Ex39"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx69","tag":"table","text":"$\\displaystyle\\left|\\left[\\boldsymbol{\\Omega}^{(k)}\\boldsymbol{\\Omega}^{(l)}\\right]_{ij}\\right|\\leq c^{2}r^{k+l},\\quad\\forall i,j,k,l.$"},{"child_ids":["A2.Ex40"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx70","tag":"table","text":"$\\displaystyle\\left|\\left[\\boldsymbol{\\Omega}^{(k_{1})}\\boldsymbol{\\Omega}^{(k_{2})}\\cdots\\boldsymbol{\\Omega}^{(k_{n})}\\right]_{ij}\\right|\\leq c^{n}r^{k_{1}+k_{2}+\\cdots+k_{n}},\\quad\\forall i,j,k_{1},\\ldots,k_{n}.$"},{"child_ids":["A2.E29"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx71","tag":"table","text":"$\\displaystyle\\begin{split}&\\left\\|\\prod_{t=t_{1}}^{t_{2}}\\left(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t)}\\right)-\\boldsymbol{I}\\right\\|_{F}\\\\ &=\\left\\|\\left(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t_{1})}\\right)\\left(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t_{1}+1)}\\right)\\cdots\\left(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t_{2})}\\right)-\\boldsymbol{I}\\right\\|_{F}\\\\ &=\\left\\|\\sum_{t_{1}\\leq k\\leq t_{2}}\\boldsymbol{\\Omega}^{(k)}+\\sum_{t_{1}\\leq k<l\\leq t_{2}}\\boldsymbol{\\Omega}^{(k)}\\boldsymbol{\\Omega}^{(l)}+\\cdots+\\boldsymbol{\\Omega}^{(t_{1})}\\boldsymbol{\\Omega}^{(t_{1}+1)}\\cdots\\boldsymbol{\\Omega}^{(t_{2})}\\right\\|_{F}\\\\ &\\leq\\left\\|\\sum_{t_{1}\\leq k\\leq t_{2}}cr^{k}\\boldsymbol{1}\\boldsymbol{1}^{\\top}+\\sum_{t_{1}\\leq k<l\\leq t_{2}}c^{2}r^{k+l}\\boldsymbol{1}\\boldsymbol{1}^{\\top}+\\cdots+c^{t2-t1+1}r^{t_{1}+\\cdots+t_{2}}\\boldsymbol{1}\\boldsymbol{1}^{\\top}\\right\\|_{F}.\\end{split}$ (29)"},{"child_ids":["A2.Ex41"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx72","tag":"table","text":"$\\displaystyle\\boldsymbol{\\Xi}:=\\sum_{T_{0}\\leq k}cr^{k}\\boldsymbol{1}\\boldsymbol{1}^{\\top}+\\sum_{T_{0}\\leq k<l}c^{2}r^{k+l}\\boldsymbol{1}\\boldsymbol{1}^{\\top}+\\sum_{T_{0}\\leq k<l<m}c^{3}r^{k+l+m}\\boldsymbol{1}\\boldsymbol{1}^{\\top}+\\cdots.$"},{"child_ids":["A2.Ex42"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx73","tag":"table","text":"$\\displaystyle\\begin{split}\\boldsymbol{\\Xi}_{ij}&=\\sum_{T_{0}\\leq k}cr^{k}+\\sum_{T_{0}\\leq k<l}c^{2}r^{k+l}+\\sum_{T_{0}\\leq k<l<m}c^{3}r^{k+l+m}+\\cdots\\\\ &<c\\sum_{k\\geq T_{0}}r^{k}+c^{2}r^{T_{0}}\\sum_{k\\geq T_{0}}r^{k}+c^{3}r^{2T_{0}}\\sum_{k\\geq T_{0}}r^{k}+\\cdots\\\\ &=\\frac{cr^{T_{0}}}{1-r}+\\frac{c^{2}r^{2T_{0}}}{1-r}+\\frac{c^{3}r^{3T_{0}}}{1-r}+\\cdots\\\\ &=\\frac{cr^{T_{0}}}{(1-r)(1-cr^{T_{0}})}\\\\ &\\leq\\frac{\\varepsilon}{d}.\\end{split}$"},{"child_ids":["A2.Ex43"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx74","tag":"table","text":"$\\displaystyle\\begin{split}\\left\\|\\prod_{t=T_{0}}^{\\infty}(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t)})-\\boldsymbol{I}\\right\\|_{F}=\\left\\|\\boldsymbol{\\Xi}\\right\\|_{F}=\\sqrt{\\sum_{i,j=1}^{d}\\boldsymbol{\\Xi}_{ij}^{2}}\\leq\\varepsilon.\\end{split}$"},{"child_ids":["A2.SS1.p1.1","A2.SS1.p1.1.1","A2.EGx66","A2.Ex36","A2.SS1.p1.2","A2.SS1.p1.2.1","A2.EGx67","A2.Ex37","A2.SS1.p1.3","A2.SS1.p1.3.1","A2.EGx68","A2.Ex38","A2.SS1.p1.4","A2.SS1.p1.4.1","A2.EGx69","A2.Ex39","A2.SS1.p1.5","A2.SS1.p1.5.1","A2.EGx70","A2.Ex40","A2.SS1.p1.6","A2.SS1.p1.6.1","A2.EGx71","A2.E29","A2.SS1.p1.7","A2.SS1.p1.7.1","A2.EGx72","A2.Ex41","A2.SS1.p1.8","A2.SS1.p1.8.1","A2.EGx73","A2.Ex42","A2.SS1.p1.9","A2.SS1.p1.9.1","A2.EGx74","A2.Ex43","A2.SS1.p1.10","A2.SS1.p1.10.1"],"classes":["ltx_para"],"id":"A2.SS1.p1","tag":"div","text":"By definition, $\\displaystyle\\left\\|\\boldsymbol{\\Omega}^{(k)}\\right\\|_{F}=\\sqrt{\\sum_{i,j=1}^{p}\\boldsymbol{\\Omega}_{ij}^{(k)2}}\\leq cr^{k},$ which implies: $\\displaystyle\\left|\\boldsymbol{\\Omega}_{ij}^{(k)}\\right|\\leq cr^{k},\\quad\\forall i,j,k.$ Consider the product of any two matrices. By sub-multiplicativity, $\\displaystyle\\left\\|\\boldsymbol{\\Omega}^{(k)}\\boldsymbol{\\Omega}^{(l)}\\right\\|_{F}\\leq\\left\\|\\boldsymbol{\\Omega}^{(k)}\\right\\|_{F}\\left\\|\\boldsymbol{\\Omega}^{(l)}\\right\\|_{F}\\leq c^{2}r^{k+l},$ which implies: $\\displaystyle\\left|\\left[\\boldsymbol{\\Omega}^{(k)}\\boldsymbol{\\Omega}^{(l)}\\right]_{ij}\\right|\\leq c^{2}r^{k+l},\\quad\\forall i,j,k,l.$ Similarly, for the product of any number of matrices: $\\displaystyle\\left|\\left[\\boldsymbol{\\Omega}^{(k_{1})}\\boldsymbol{\\Omega}^{(k_{2})}\\cdots\\boldsymbol{\\Omega}^{(k_{n})}\\right]_{ij}\\right|\\leq c^{n}r^{k_{1}+k_{2}+\\cdots+k_{n}},\\quad\\forall i,j,k_{1},\\ldots,k_{n}.$ Thus $\\displaystyle\\begin{split}&\\left\\|\\prod_{t=t_{1}}^{t_{2}}\\left(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t)}\\right)-\\boldsymbol{I}\\right\\|_{F}\\\\ &=\\left\\|\\left(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t_{1})}\\right)\\left(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t_{1}+1)}\\right)\\cdots\\left(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t_{2})}\\right)-\\boldsymbol{I}\\right\\|_{F}\\\\ &=\\left\\|\\sum_{t_{1}\\leq k\\leq t_{2}}\\boldsymbol{\\Omega}^{(k)}+\\sum_{t_{1}\\leq k<l\\leq t_{2}}\\boldsymbol{\\Omega}^{(k)}\\boldsymbol{\\Omega}^{(l)}+\\cdots+\\boldsymbol{\\Omega}^{(t_{1})}\\boldsymbol{\\Omega}^{(t_{1}+1)}\\cdots\\boldsymbol{\\Omega}^{(t_{2})}\\right\\|_{F}\\\\ &\\leq\\left\\|\\sum_{t_{1}\\leq k\\leq t_{2}}cr^{k}\\boldsymbol{1}\\boldsymbol{1}^{\\top}+\\sum_{t_{1}\\leq k<l\\leq t_{2}}c^{2}r^{k+l}\\boldsymbol{1}\\boldsymbol{1}^{\\top}+\\cdots+c^{t2-t1+1}r^{t_{1}+\\cdots+t_{2}}\\boldsymbol{1}\\boldsymbol{1}^{\\top}\\right\\|_{F}.\\end{split}$ (29) Note that the last inequality can be checked by comparing matrix elements of both sides. For any $\\varepsilon>0$ , we take $T_{0}=\\lceil\\log_{r}\\frac{(1-r)(\\varepsilon/d)}{c(1+(1-r)(\\varepsilon/d))}\\rceil$ . Consider $t_{1}=T_{0}$ and $t_{2}\\rightarrow\\infty$ in (29 ). For notation convenience, let $\\displaystyle\\boldsymbol{\\Xi}:=\\sum_{T_{0}\\leq k}cr^{k}\\boldsymbol{1}\\boldsymbol{1}^{\\top}+\\sum_{T_{0}\\leq k<l}c^{2}r^{k+l}\\boldsymbol{1}\\boldsymbol{1}^{\\top}+\\sum_{T_{0}\\leq k<l<m}c^{3}r^{k+l+m}\\boldsymbol{1}\\boldsymbol{1}^{\\top}+\\cdots.$ Then $\\displaystyle\\begin{split}\\boldsymbol{\\Xi}_{ij}&=\\sum_{T_{0}\\leq k}cr^{k}+\\sum_{T_{0}\\leq k<l}c^{2}r^{k+l}+\\sum_{T_{0}\\leq k<l<m}c^{3}r^{k+l+m}+\\cdots\\\\ &<c\\sum_{k\\geq T_{0}}r^{k}+c^{2}r^{T_{0}}\\sum_{k\\geq T_{0}}r^{k}+c^{3}r^{2T_{0}}\\sum_{k\\geq T_{0}}r^{k}+\\cdots\\\\ &=\\frac{cr^{T_{0}}}{1-r}+\\frac{c^{2}r^{2T_{0}}}{1-r}+\\frac{c^{3}r^{3T_{0}}}{1-r}+\\cdots\\\\ &=\\frac{cr^{T_{0}}}{(1-r)(1-cr^{T_{0}})}\\\\ &\\leq\\frac{\\varepsilon}{d}.\\end{split}$ Thus $\\displaystyle\\begin{split}\\left\\|\\prod_{t=T_{0}}^{\\infty}(\\boldsymbol{I}+\\boldsymbol{\\Omega}^{(t)})-\\boldsymbol{I}\\right\\|_{F}=\\left\\|\\boldsymbol{\\Xi}\\right\\|_{F}=\\sqrt{\\sum_{i,j=1}^{d}\\boldsymbol{\\Xi}_{ij}^{2}}\\leq\\varepsilon.\\end{split}$ Hence completes the proof. ∎"},{"child_ids":["A2.SS1.p2.1","A2.SS1.p2.1.1"],"classes":["ltx_para","ltx_noindent"],"id":"A2.SS1.p2","tag":"div","text":"In the following proof, we treat $\\boldsymbol{Z},\\boldsymbol{X},\\boldsymbol{Y}$ as deterministic matrices."},{"child_ids":["A2.Ex44"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx75","tag":"table","text":"$\\displaystyle\\begin{split}\\boldsymbol{\\Theta}^{(t)}-\\hat{\\boldsymbol{\\Theta}}&=\\boldsymbol{\\Theta}^{(t-1)}-\\hat{\\boldsymbol{\\Theta}}-\\eta\\boldsymbol{Z}^{\\top}\\left(\\boldsymbol{Z\\Theta}^{(t-1)}-\\boldsymbol{X}\\right)\\\\ &=\\left(\\boldsymbol{I}-\\eta\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}\\right)\\left(\\boldsymbol{\\Theta}^{(t-1)}-\\hat{\\boldsymbol{\\Theta}}\\right)+\\eta\\boldsymbol{Z}^{\\top}\\left(\\boldsymbol{X}-\\boldsymbol{Z\\hat{\\Theta}}\\right)\\\\ &=\\left(\\boldsymbol{I}-\\eta\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}\\right)^{2}\\left(\\boldsymbol{\\Theta}^{(t-2)}-\\hat{\\boldsymbol{\\Theta}}\\right)+\\eta\\boldsymbol{Z}^{\\top}\\left(\\boldsymbol{X}-\\boldsymbol{Z\\hat{\\Theta}}\\right)+\\eta\\left(\\boldsymbol{I}-\\eta\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}\\right)\\boldsymbol{Z}^{\\top}\\left(\\boldsymbol{X}-\\boldsymbol{Z\\hat{\\Theta}}\\right)\\\\ &\\quad\\quad\\quad\\quad\\quad\\quad\\quad\\quad\\vdots\\\\ &=\\left(\\boldsymbol{I}-\\eta\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}\\rig