t)\\right\\|_{F}<\\sqrt{p}+1.$ (32) Hence $\\displaystyle\\begin{split}\\left\\|\\boldsymbol{\\Delta}_{1}\\boldsymbol{\\beta}^{(t)}\\right\\|&=\\left\\|\\boldsymbol{V}^{(t)}\\prod_{i=0}^{t-1}(\\boldsymbol{I}-\\boldsymbol{\\Psi W}^{(i)})(\\boldsymbol{\\beta}^{(0)}-\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})\\right\\|\\\\ &\\leq\\left\\|\\boldsymbol{V}^{(t)}\\right\\|\\left\\|\\prod_{i=0}^{T_{0}-1}\\left(\\boldsymbol{I}-\\boldsymbol{\\Psi W}^{(i)}\\right)\\right\\|\\left\\|\\prod_{i=T_{0}}^{t-1}(\\boldsymbol{I}-\\boldsymbol{\\Psi W}^{(i)})\\right\\|\\left\\|\\boldsymbol{\\beta}^{(0)}-\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}\\right\\|\\\\ &<\\gamma(\\alpha)^{t}\\left\\|\\prod_{i=0}^{T_{0}-1}\\left(\\boldsymbol{I}-\\boldsymbol{\\Psi W}^{(i)}\\right)\\right\\|\\left(\\sqrt{p}+1\\right)\\left\\|\\boldsymbol{\\beta}^{(0)}-\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}\\right\\|\\\\ &=\\mathcal{O}(\\gamma(\\alpha)^{t}).\\end{split}$ (33) Next we consider $\\boldsymbol{\\Delta}_{2}\\boldsymbol{\\beta}^{(t)}$ : $\\displaystyle\\begin{split}\\boldsymbol{\\Delta}_{2}\\boldsymbol{\\beta}^{(t)}&=\\sum_{i=0}^{t-1}\\alpha\\left[\\prod_{j=i+1}^{t-1}\\left(\\boldsymbol{I}-\\alpha\\boldsymbol{\\Theta}^{(j)\\top}\\boldsymbol{Z}^{\\top}\\boldsymbol{Z\\Theta}^{(j)}\\right)\\right]\\boldsymbol{\\Theta}^{(i)\\top}\\boldsymbol{Z}^{\\top}\\left(\\boldsymbol{Y}-\\boldsymbol{Z\\Theta}^{(i)}\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}\\right)\\\\ &=\\sum_{i=0}^{t-1}\\alpha\\left[\\prod_{j=i+1}^{t-1}\\left(\\boldsymbol{I}-\\alpha\\hat{\\boldsymbol{\\Theta}}^{\\top}\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}\\hat{\\boldsymbol{\\Theta}}-\\alpha\\boldsymbol{W}^{(j)}\\right)\\right]\\left(\\boldsymbol{R}^{(i)}+\\hat{\\boldsymbol{\\Theta}}\\right)^{\\top}\\boldsymbol{Z}^{\\top}\\left[\\boldsymbol{Y}-\\boldsymbol{Z}\\left(\\boldsymbol{R}^{(i)}+\\hat{\\boldsymbol{\\Theta}}\\right)\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}\\right]\\\\ &=\\sum_{i=0}^{t-1}\\alpha\\left(\\boldsymbol{I}-\\alpha\\hat{\\boldsymbol{\\Theta}}^{\\top}\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}\\hat{\\boldsymbol{\\Theta}}\\right)^{t-1-i}\\prod_{j=i+1}^{t-1}\\left[\\boldsymbol{I}-\\alpha\\left(\\boldsymbol{I}-\\alpha\\hat{\\boldsymbol{\\Theta}}^{\\top}\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}\\hat{\\boldsymbol{\\Theta}}\\right)^{-1}\\boldsymbol{W}^{(j)}\\right]\\\\ &\\quad\\quad\\quad\\quad\\cdot\\left(\\boldsymbol{R}^{(i)}+\\hat{\\boldsymbol{\\Theta}}\\right)^{\\top}\\boldsymbol{Z}^{\\top}\\left[\\boldsymbol{Y}-\\boldsymbol{Z}\\left(\\boldsymbol{R}^{(i)}+\\hat{\\boldsymbol{\\Theta}}\\right)\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}\\right]\\\\ &=\\sum_{i=0}^{t-1}\\alpha\\left[\\boldsymbol{V}^{(t-1-i)}\\prod_{j=i+1}^{t-1}\\left(\\boldsymbol{I}-\\boldsymbol{\\Psi}\\boldsymbol{W}^{(j)}\\right)\\right]\\left(\\boldsymbol{R}^{(i)}+\\hat{\\boldsymbol{\\Theta}}\\right)^{\\top}\\boldsymbol{Z}^{\\top}\\left[\\boldsymbol{Y}-\\boldsymbol{Z}\\left(\\boldsymbol{R}^{(i)}+\\hat{\\boldsymbol{\\Theta}}\\right)\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}\\right].\\end{split}$ For convenience, let $\\boldsymbol{\\Delta}_{2}\\boldsymbol{\\beta}^{(t)}:=\\boldsymbol{\\Delta}_{21}\\boldsymbol{\\beta}^{(t)}+\\boldsymbol{\\Delta}_{22}\\boldsymbol{\\beta}^{(t)}$ , where $\\displaystyle\\boldsymbol{\\Delta}_{21}\\boldsymbol{\\beta}^{(t)}:$ $\\displaystyle=\\sum_{i=0}^{t-1}\\alpha\\left[\\boldsymbol{V}^{(t-1-i)}\\prod_{j=i+1}^{t-1}\\left(\\boldsymbol{I}-\\boldsymbol{\\Psi}\\boldsymbol{W}^{(j)}\\right)\\right]\\boldsymbol{R}^{(i)\\top}\\boldsymbol{Z}^{\\top}\\left[\\boldsymbol{Y}-\\boldsymbol{Z}\\left(\\boldsymbol{R}^{(i)}+\\hat{\\boldsymbol{\\Theta}}\\right)\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}\\right],$ $\\displaystyle\\boldsymbol{\\Delta}_{22}\\boldsymbol{\\beta}^{(t)}:$ $\\displaystyle=\\sum_{i=0}^{t-1}\\alpha\\left[\\boldsymbol{V}^{(t-1-i)}\\prod_{j=i+1}^{t-1}\\left(\\boldsymbol{I}-\\boldsymbol{\\Psi}\\boldsymbol{W}^{(j)}\\right)\\right]\\hat{\\boldsymbol{\\Theta}}^{\\top}\\boldsymbol{Z}^{\\top}\\left[\\boldsymbol{Y}-\\boldsymbol{Z}\\left(\\boldsymbol{R}^{(i)}+\\hat{\\boldsymbol{\\Theta}}\\right)\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}\\right].$ Suppose $\\tilde{M}_{1},\\tilde{M}_{2}$ are the upper bounds such that $\\displaystyle\\left\\|\\boldsymbol{Z}^{\\top}\\left[\\boldsymbol{Y}-\\boldsymbol{Z}\\left(\\boldsymbol{R}^{(i)}+\\hat{\\boldsymbol{\\Theta}}\\right)\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}\\right]\\right\\|\\leq\\tilde{M}_{1},\\quad\\forall i=0,\\ldots,t-1,$ $\\displaystyle\\left\\|\\prod_{j=i+1}^{t-1}\\left(\\boldsymbol{I}-\\boldsymbol{\\Psi}\\boldsymbol{W}^{(j)}\\right)\\right\\|\\leq\\tilde{M}_{2},\\quad\\forall i=0,\\ldots,t-1.$ We know such $\\tilde{M}_{1},\\tilde{M}_{2}$ exist because of the bounds given by (31 ) and (32 ). Let $\\tilde{M}=\\tilde{M}_{1}\\tilde{M}_{2}$ . Then $\\displaystyle\\begin{split}\\left\\|\\boldsymbol{\\Delta}_{21}\\boldsymbol{\\beta}^{(t)}\\right\\|&\\leq\\tilde{M}\\left\\|\\sum_{i=0}^{t-1}\\alpha\\boldsymbol{V}^{(t-1-i)}\\boldsymbol{R}^{(i)\\top}\\right\\|\\\\ &\\leq\\tilde{M}\\alpha\\sum_{i=0}^{t-1}\\left\\|\\boldsymbol{V}^{(t-1-i)}\\right\\|\\left\\|\\boldsymbol{R}^{(i)}\\right\\|\\\\ &\\leq\\tilde{M}\\alpha\\left\\|\\boldsymbol{\\Theta}^{(0)}-\\hat{\\boldsymbol{\\Theta}}\\right\\|\\sum_{i=0}^{t-1}\\gamma(\\alpha)^{t-1-i}\\kappa(\\eta)^{i}\\\\ &=\\tilde{M}\\alpha\\left\\|\\boldsymbol{\\Theta}^{(0)}-\\hat{\\boldsymbol{\\Theta}}\\right\\|\\sum_{i=0}^{t-1}\\gamma(\\alpha)^{t-1}\\left(\\frac{\\kappa(\\eta)}{\\gamma(\\alpha)}\\right)^{i}\\\\ &=\\mathcal{O}\\left(\\frac{\\gamma(\\alpha)^{t}-\\kappa(\\eta)^{t}}{\\gamma(\\alpha)-\\kappa(\\eta)}\\right)\\\\ &\\leq\\mathcal{O}(\\max\\{\\gamma(\\alpha)^{t},\\kappa(\\eta)^{t}\\}),\\end{split}$ and similarly, $\\displaystyle\\begin{split}\\left\\|\\boldsymbol{\\Delta}_{22}\\boldsymbol{\\beta}^{(t)}\\right\\|&\\leq\\tilde{M}\\left\\|\\sum_{i=0}^{t-1}\\alpha\\boldsymbol{V}^{(t-1-i)}\\hat{\\boldsymbol{\\Theta}}^{T}\\right\\|\\\\ &\\leq\\tilde{M}\\alpha\\left\\|\\hat{\\boldsymbol{\\Theta}}\\right\\|\\sum_{i=0}^{t-1}\\left\\|\\boldsymbol{V}^{(t-1-i)}\\right\\|\\\\ &\\leq\\tilde{M}\\alpha\\left\\|\\hat{\\boldsymbol{\\Theta}}\\right\\|\\sum_{i=0}^{t-1}\\gamma(\\alpha)^{t-1-i}\\\\ &=\\mathcal{O}(\\gamma(\\alpha)^{t}).\\end{split}$ Thus $\\displaystyle\\begin{split}\\left\\|\\boldsymbol{\\Delta}_{2}\\boldsymbol{\\beta}^{(t)}\\right\\|&=\\left\\|\\boldsymbol{\\Delta}_{21}\\boldsymbol{\\beta}^{(t)}+\\boldsymbol{\\Delta}_{22}\\boldsymbol{\\beta}^{(t)}\\right\\|\\\\ &\\leq\\left\\|\\boldsymbol{\\Delta}_{21}\\boldsymbol{\\beta}^{(t)}\\right\\|+\\left\\|\\boldsymbol{\\Delta}_{22}\\boldsymbol{\\beta}^{(t)}\\right\\|\\\\ &\\leq\\mathcal{O}(\\max\\{\\gamma(\\alpha)^{t},\\kappa(\\eta)^{t}\\}).\\end{split}$ (34) Therefore, plugging (33 ) and (34 ) into (30 ), we have: $\\displaystyle\\left\\|\\boldsymbol{\\beta}^{(t)}-\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}\\right\\|\\leq\\mathcal{O}(\\max\\{\\gamma(\\alpha)^{t},\\kappa(\\eta)^{t}\\}),$ Hence completes the proof. ∎"},{"child_ids":["A2.Ex63"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx93","tag":"table","text":"$\\displaystyle\\boldsymbol{H}^{(0)}=\\begin{bmatrix}\\boldsymbol{z}_{1}&\\cdots&\\boldsymbol{z}_{n}&\\boldsymbol{z}_{n+1}\\\\ \\boldsymbol{x}_{1}&\\cdots&\\boldsymbol{x}_{n}&\\boldsymbol{x}_{n+1}\\\\ y_{1}&\\cdots&y_{n}&0\\\\ \\boldsymbol{\\Theta}_{:,1}^{(0)}&\\cdots&\\boldsymbol{\\Theta}_{:,1}^{(0)}&\\boldsymbol{\\Theta}_{:,1}^{(0)}\\\\ \\vdots&\\vdots&\\vdots&\\vdots\\\\ \\boldsymbol{\\Theta}_{:,p}^{(0)}&\\cdots&\\boldsymbol{\\Theta}_{:,p}^{(0)}&\\boldsymbol{\\Theta}_{:,p}^{(0)}\\\\ \\boldsymbol{\\beta}^{(0)}&\\cdots&\\boldsymbol{\\beta}^{(0)}&\\boldsymbol{\\beta}^{(0)}\\\\ \\hat{\\boldsymbol{x}}_{1}^{(0)}&\\cdots&\\hat{\\boldsymbol{x}}_{n}^{(0)}&\\hat{\\boldsymbol{x}}_{n+1}^{(0)}\\\\ 1&\\cdots&1&1\\\\ 1&\\cdots&1&0\\end{bmatrix}\\in\\mathbb{R}^{D\\times(n+1)},$"},{"child_ids":["A2.Ex64"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx94