t_{j}-R^{\\prime}(1-t_{j})\\right)\\\\ &=\\sigma\\left(\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}-y_{j}\\right)\\mathbbm{1}\\{t_{j}=1\\}\\\\ &=\\sigma\\left(\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}-y_{j}\\right)t_{j},\\end{split}$"},{"child_ids":["A2.Ex71"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx107","tag":"table","text":"$\\displaystyle\\begin{split}\\sigma\\left(\\langle\\boldsymbol{Q}_{2p+2}^{(2)}\\boldsymbol{h}_{i}^{(1)},\\boldsymbol{K}_{2p+2}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\rangle\\right)&=\\sigma\\left(-\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}+y_{j}t_{j}-R^{\\prime}(1-t_{j})\\right)\\\\ &=\\sigma\\left(-\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}+y_{j}\\right)\\mathbbm{1}\\{t_{j}=1\\}\\\\ &=\\sigma\\left(-\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}+y_{j}\\right)t_{j}.\\end{split}$"},{"child_ids":["A2.Ex72"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx108","tag":"table","text":"$\\displaystyle\\begin{split}&\\sum_{m=2p+1}^{2p+2}\\sigma\\left(\\langle\\boldsymbol{Q}_{m}^{(2)}\\boldsymbol{h}_{i}^{(1)},\\boldsymbol{K}_{m}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\rangle\\right)\\boldsymbol{V}_{m}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\\\ &=-(n+1)t_{j}\\alpha\\left[\\sigma\\left(\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}-y_{j}\\right)-\\sigma\\left(-\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}+y_{j}\\right)\\right]\\cdot\\sum_{l=1}^{p}\\hat{x}_{jl}^{(1)}\\boldsymbol{e}_{D_{0}+qp+l}\\\\ &=-(n+1)t_{j}\\alpha\\sum_{l=1}^{p}\\hat{x}_{jl}^{(1)}\\left(\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}-y_{j}\\right)\\boldsymbol{e}_{D_{0}+qp+l}.\\end{split}$"},{"child_ids":["A2.Ex73"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx109","tag":"table","text":"$\\displaystyle\\begin{split}\\boldsymbol{h}_{i}^{(2)}&=\\boldsymbol{h}_{i}^{(1)}+\\sum_{m=1}^{2p+2}\\frac{1}{n+1}\\sum_{j=1}^{n}\\sigma\\left(\\langle\\boldsymbol{Q}_{m}^{(2)}\\boldsymbol{h}_{i}^{(1)},\\boldsymbol{K}_{m}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\rangle\\right)\\boldsymbol{V}_{m}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\\\ &=\\begin{bmatrix}\\boldsymbol{z}_{i}\\\\ \\boldsymbol{x}_{i}\\\\ y_{i}t_{i}\\\\ \\boldsymbol{\\Theta}_{:,1}^{(0)}-\\eta\\sum_{j=1}^{n}\\boldsymbol{z}_{j}\\left(\\boldsymbol{z}_{j}^{\\top}\\boldsymbol{\\Theta}_{:,1}^{(0)}-x_{j1}\\right)\\\\ \\vdots\\\\ \\boldsymbol{\\Theta}_{:,p}^{(0)}-\\eta\\sum_{j=1}^{n}\\boldsymbol{z}_{j}\\left(\\boldsymbol{z}_{j}^{\\top}\\boldsymbol{\\Theta}_{:,p}^{(0)}-x_{jp}\\right)\\\\ \\boldsymbol{\\beta}^{(0)}-\\alpha\\sum_{j=1}^{n}\\hat{\\boldsymbol{x}}_{j}^{(1)}\\left(\\hat{\\boldsymbol{x}}_{j}^{(1)\\top}\\boldsymbol{\\beta}^{(0)}-y_{j}\\right)\\\\ \\hat{\\boldsymbol{x}}_{i}^{(1)}\\\\ 1\\\\ t_{i}\\end{bmatrix}\\\\ &=\\begin{bmatrix}\\boldsymbol{z}_{i}\\\\ \\boldsymbol{x}_{i}\\\\ y_{i}t_{i}\\\\ \\boldsymbol{\\Theta}_{:,1}^{(0)}-\\eta\\boldsymbol{Z}^{\\top}\\left[\\boldsymbol{Z\\Theta}^{(0)}-\\boldsymbol{X}\\right]_{:,1}\\\\ \\vdots\\\\ \\boldsymbol{\\Theta}_{:,p}^{(0)}-\\eta\\boldsymbol{Z}^{\\top}\\left[\\boldsymbol{Z\\Theta}^{(0)}-\\boldsymbol{X}\\right]_{:,p}\\\\ \\boldsymbol{\\beta}^{(0)}-\\alpha\\boldsymbol{\\Theta}^{(0)\\top}\\boldsymbol{Z}^{\\top}\\left(\\boldsymbol{Z\\Theta}^{(0)}\\boldsymbol{\\beta}^{(0)}-\\boldsymbol{y}\\right)\\\\ \\hat{\\boldsymbol{x}}_{i}^{(1)}\\\\ 1\\\\ t_{i}\\end{bmatrix}.\\end{split}$"},{"child_ids":["A2.SS2.p8.1","A2.SS2.p8.1.1","A2.EGx100","A2.E38","A2.SS2.p8.2","A2.SS2.p8.2.1","A2.EGx101","A2.Ex67","A2.SS2.p8.3","A2.SS2.p8.3.1","A2.EGx102","A2.Ex68","A2.SS2.p8.4","A2.SS2.p8.4.1","A2.EGx103","A2.Ex69","A2.SS2.p8.5","A2.SS2.p8.5.1","A2.EGx104","A2.E39","A2.EGx105","A2.E40","A2.SS2.p8.6","A2.SS2.p8.6.1","A2.EGx106","A2.Ex70","A2.SS2.p8.7","A2.SS2.p8.7.1","A2.EGx107","A2.Ex71","A2.SS2.p8.8","A2.SS2.p8.8.1","A2.EGx108","A2.Ex72","A2.SS2.p8.9","A2.SS2.p8.9.1","A2.EGx109","A2.Ex73","A2.SS2.p8.10","A2.SS2.p8.10.1"],"classes":["ltx_para","ltx_noindent"],"id":"A2.SS2.p8","tag":"div","text":"For $m=2k,k=1,\\ldots,p$ , define $\\boldsymbol{Q}_{m}^{(2)},\\boldsymbol{K}_{m}^{(2)},\\boldsymbol{V}_{m}^{(2)}$ such that: $\\displaystyle\\boldsymbol{Q}_{m}^{(2)}\\boldsymbol{h}_{i}^{(1)}=\\begin{bmatrix}-\\boldsymbol{\\Theta}_{:,k}^{(0)}\\\\ 1\\\\ -1\\\\ \\vdots\\\\ \\boldsymbol{0}\\end{bmatrix},\\boldsymbol{K}_{m}^{(2)}\\boldsymbol{h}_{j}^{(1)}=\\begin{bmatrix}\\boldsymbol{z}_{j}\\\\ x_{jk}t_{j}\\\\ R(1-t_{j})\\\\ \\vdots\\\\ \\boldsymbol{0}\\end{bmatrix},\\boldsymbol{V}_{m}^{(2)}\\boldsymbol{h}_{j}^{(1)}=(n+1)\\eta\\sum_{l=1}^{q}z_{jl}\\boldsymbol{e}_{D_{0}+(k-1)q+l},$ (38) where $R=\\underset{\\begin{subarray}{c}i=1,\\ldots,n+1\\\\ t=0,1,\\ldots\\end{subarray}}{\\max}\\{||\\boldsymbol{\\Theta}^{(t)\\top}\\boldsymbol{z}_{i}||\\}$ . Then we have: $\\displaystyle\\begin{split}\\sigma\\left(\\langle\\boldsymbol{Q}_{2k-1}^{(2)}\\boldsymbol{h}_{i}^{(1)},\\boldsymbol{K}_{2k-1}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\rangle\\right)&=\\sigma\\left(\\boldsymbol{\\Theta}_{:,k}^{(0)\\top}\\boldsymbol{z}_{j}-x_{jk}t_{j}-R(1-t_{j})\\right)\\\\ &=\\sigma\\left(\\boldsymbol{\\Theta}_{:,k}^{(0)\\top}\\boldsymbol{z}_{j}-x_{jk}\\right)\\mathbbm{1}\\{t_{j}=1\\}\\\\ &=\\sigma\\left(\\boldsymbol{\\Theta}_{:,k}^{(0)\\top}\\boldsymbol{z}_{j}-x_{jk}\\right)t_{j},\\\\ \\end{split}$ and $\\displaystyle\\begin{split}\\sigma\\left(\\langle\\boldsymbol{Q}_{2k}^{(2)}\\boldsymbol{h}_{i}^{(1)},\\boldsymbol{K}_{2k}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\rangle\\right)&=\\sigma\\left(-\\boldsymbol{\\Theta}_{:,k}^{(0)\\top}\\boldsymbol{z}_{j}+x_{jk}t_{j}-R(1-t_{j})\\right)\\\\ &=\\sigma\\left(-\\boldsymbol{\\Theta}_{:,k}^{(0)\\top}\\boldsymbol{z}_{j}+x_{jk}\\right)\\mathbbm{1}\\{t_{j}=1\\}\\\\ &=\\sigma\\left(-\\boldsymbol{\\Theta}_{:,k}^{(0)\\top}\\boldsymbol{z}_{j}+x_{jk}\\right)t_{j}.\\end{split}$ So that $\\displaystyle\\begin{split}&\\sum_{m=1}^{2p}\\sigma\\left(\\langle\\boldsymbol{Q}_{m}^{(2)}\\boldsymbol{h}_{i}^{(1)},\\boldsymbol{K}_{m}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\rangle\\right)\\boldsymbol{V}_{m}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\\\ &=-(n+1)t_{j}\\eta\\sum_{k=1}^{p}\\left[\\sigma\\left(\\boldsymbol{\\Theta}_{:,k}^{(0)\\top}\\boldsymbol{z}_{j}-x_{jk}\\right)-\\sigma\\left(-\\boldsymbol{\\Theta}_{:,k}^{(0)\\top}\\boldsymbol{z}_{j}+x_{jk}\\right)\\right]\\cdot\\sum_{l=1}^{q}z_{jl}\\boldsymbol{e}_{D_{0}+(k-1)q+l}\\\\ &=-(n+1)t_{j}\\eta\\sum_{k=1}^{p}\\sum_{l=1}^{q}z_{jl}\\left(\\boldsymbol{\\Theta}_{:,k}^{(0)\\top}\\boldsymbol{z}_{j}-x_{jk}\\right)\\boldsymbol{e}_{D_{0}+(k-1)q+l}.\\end{split}$ Similarly, for $m=2p+1,2p+2$ , define $\\boldsymbol{Q}_{m}^{(2)},\\boldsymbol{K}_{m}^{(2)},\\boldsymbol{V}_{m}^{(2)}$ such that: $\\displaystyle\\boldsymbol{Q}_{2p+1}^{(2)}\\boldsymbol{h}_{i}^{(1)}=\\begin{bmatrix}\\boldsymbol{\\beta}^{(0)}\\\\ -1\\\\ -1\\\\ \\vdots\\\\ \\boldsymbol{0}\\end{bmatrix},\\boldsymbol{K}_{2p+1}^{(2)}\\boldsymbol{h}_{j}^{(1)}=\\begin{bmatrix}\\hat{\\boldsymbol{x}}_{j}^{(1)}\\\\ y_{j}t_{j}\\\\ R^{\\prime}(1-t_{j})\\\\ \\vdots\\\\ \\boldsymbol{0}\\end{bmatrix},\\boldsymbol{V}_{2p+1}\\boldsymbol{h}_{j}^{(1)}=-(n+1)\\alpha\\sum_{l=1}^{p}\\hat{x}_{jl}^{(1)}\\boldsymbol{e}_{D_{0}+qp+l},$ (39) $\\displaystyle\\boldsymbol{Q}_{2p+2}^{(2)}\\boldsymbol{h}_{i}^{(1)}=\\begin{bmatrix}-\\boldsymbol{\\beta}^{(0)}\\\\ 1\\\\ -1\\\\ \\vdots\\\\ \\boldsymbol{0}\\end{bmatrix},\\boldsymbol{K}_{2p+2}^{(2)}\\boldsymbol{h}_{j}^{(1)}=\\begin{bmatrix}\\hat{\\boldsymbol{x}}_{j}^{(1)}\\\\ y_{j}t_{j}\\\\ R^{\\prime}(1-t_{j})\\\\ \\vdots\\\\ \\boldsymbol{0}\\end{bmatrix},\\boldsymbol{V}_{2p+2}\\boldsymbol{h}_{j}^{(1)}=(n+1)\\alpha\\sum_{l=1}^{p}\\hat{x}_{jl}^{(1)}\\boldsymbol{e}_{D_{0}+qp+l},$ (40) where $R^{\\prime}=\\underset{\\begin{subarray}{c}i=1,\\ldots,n+1\\\\ t=0,1,\\ldots\\end{subarray}}{\\max}\\{|\\boldsymbol{\\beta}^{(t)\\top}\\boldsymbol{x}_{i}|\\}$ . Then $\\displaystyle\\begin{split}\\sigma\\left(\\langle\\boldsymbol{Q}_{2p+1}^{(2)}\\boldsymbol{h}_{i}^{(1)},\\boldsymbol{K}_{2p+1}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\rangle\\right)&=\\sigma\\left(\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}-y_{j}t_{j}-R^{\\prime}(1-t_{j})\\right)\\\\ &=\\sigma\\left(\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}-y_{j}\\right)\\mathbbm{1}\\{t_{j}=1\\}\\\\ &=\\sigma\\left(\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}-y_{j}\\right)t_{j},\\end{split}$ and $\\displaystyle\\begin{split}\\sigma\\left(\\langle\\boldsymbol{Q}_{2p+2}^{(2)}\\boldsymbol{h}_{i}^{(1)},\\boldsymbol{K}_{2p+2}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\rangle\\right)&=\\sigma\\left(-\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}+y_{j}t_{j}-R^{\\prime}(1-t_{j})\\right)\\\\ &=\\sigma\\left(-\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}+y_{j}\\right)\\mathbbm{1}\\{t_{j}=1\\}\\\\ &=\\sigma\\left(-\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}+y_{j}\\right)t_{j}.\\end{split}$ So that $\\displaystyle\\begin{split}&\\sum_{m=2p+1}^{2p+2}\\sigma\\left(\\langle\\boldsymbol{Q}_{m}^{(2)}\\boldsymbol{h}_{i}^{(1)},\\boldsymbol{K}_{m}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\rangle\\right)\\boldsymbol{V}_{m}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\\\ &=-(n+1)t_{j}\\alpha\\left[\\sigma\\left(\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}-y_{j}\\right)-\\sigma\\left(-\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}+y_{j}\\right)\\right]\\cdot\\sum_{l=1}^{p}\\hat{x}_{jl}^{(1)}\\boldsymbol{e}_{D_{0}+qp+l}\\\\ &=-(n+1)t_{j}\\alpha\\sum_{l=1}^{p}\\hat{x}_{jl}^{(1)}\\left(\\boldsymbol{\\beta}^{(0)\\top}\\hat{\\boldsymbol{x}}_{j}^{(1)}-y_{j}\\right)\\boldsymbol{e}_{D_{0}+qp+l}.\\end{split}$ Thus the final output, for $i=1,\\ldots,n+1$ : $\\displaystyle\\begin{split}\\boldsymbol{h}_{i}^{(2)}&=\\boldsymbol{h}_{i}^{(1)}+\\sum_{m=1}^{2p+2}\\frac{1}{n+1}\\sum_{j=1}^{n}\\sigma\\left(\\langle\\boldsymbol{Q}_{m}^{(2)}\\boldsymbol{h}_{i}^{(1)},\\boldsymbol{K}_{m}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\rangle\\right)\\boldsymbol{V}_{m}^{(2)}\\boldsymbol{h}_{j}^{(1)}\\\\ &=\\begin{bmatrix}\\boldsymbol{z}_{i}\\\\ \\boldsymbol{x}_{i}\\\\ y_{i}t_{i}\\\\ \\boldsymbol{\\Theta}_{:,1}^{(0)}-\\eta\\sum_{j=1}^{n}\\boldsymbol{z}_{j}\\left(\\boldsymbol{z}_{j}^{\\top}\\boldsymbol{\\Theta}_{:,1}^{(0)}-x_{j1}\\right)\\\\ \\vdots\\\\ \\boldsymbol{\\Theta}_{:,p}^{(0)}-\\eta\\sum_{j=1}^{n}\\boldsymbol{z}_{j}\\left(\\boldsymbol{z}_{j}^{\\top}\\boldsymbol{\\Theta}_{:,p}^{(0)}-x_{jp}\\right)\\\\ \\boldsymbol{\\beta}^{(0)}-\\alpha\\sum_{j=1}^{n}\\hat{\\boldsymbol{x}}_{j}^{(1)}\\left(\\hat{\\boldsymbol{x}}_{j}^{(1)\\top}\\boldsymbol{\\beta}^{(0)}-y_{j}\\right)\\\\ \\hat{\\boldsymbol{x}}_{i}^{(1)}\\\\ 1\\\\ t_{i}\\end{bmatrix}\\\\ &=\\begin{bmatrix}\\boldsymbol{z}_{i}\\\\ \\boldsymbol{x}_{i}\\\\ y_{i}t_{i}\\\\ \\boldsymbol{\\Theta}_{:,1}^{(0)}-\\eta\\boldsymbol{Z}^{\\top}\\left[\\boldsymbol{Z\\Theta}^{(0)}-\\boldsymbol{X}\\right]_{:,1}\\\\ \\vdots\\\\ \\boldsymbol{\\Theta}_{:,p}^{(0)}-\\eta\\boldsymbol{Z}^{\\top}\\left[\\boldsymbol{Z\\Theta}^{(0)}-\\boldsymbol{X}\\right]_{:,p}\\\\ \\boldsymbol{\\beta}^{(0)}-\\alpha\\boldsymbol{\\Theta}^{(0)\\top}\\boldsymbol{Z}^{\\top}\\left(\\boldsymbol{Z\\Theta}^{(0)}\\boldsymbol{\\beta}^{(0)}-\\boldsymbol{y}\\right)\\\\ \\hat{\\boldsymbol{x}}_{i}^{(1)}\\\\ 1\\\\ t_{i}\\end{bmatrix}.\\end{split}$ This corresponds to a one-step 2SLS GD update of $\\boldsymbol{\\Theta},\\boldsymbol{\\beta}$ , according to (8 ). Therefore, the final output matrix is:"},{"child_ids":["A2.Ex74"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx110","tag":"table","text":"$\\displaystyle\\boldsymbol{H}^{(2)}=\\begin{bmatrix}\\boldsymbol{z}_{1}&\\cdots&\\boldsymbol{z}_{n}&\\boldsymbol{z}_{n+1}\\\\ \\boldsymbol{x}_{1}&\\cdots&\\boldsymbol{x}_{n}&\\boldsymbol{x}_{n+1}\\\\ y_{1}&\\cdots&y_{n}&0\\\\ \\boldsymbol{\\Theta}_{:,1}^{(1)}&\\cdots&\\boldsymbol{\\Theta}_{:,1}^{(1)}&\\boldsymbol{\\Theta}_{:,1}^{(1)}\\\\ \\vdots&\\vdots&\\vdots&\\vdots\\\\ \