(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle\\right|\\leq\\mathcal{O}\\left(B_{x}\\Lambda^{\\bar{L}}\\right).$"},{"child_ids":["A2.E43"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx116","tag":"table","text":"$\\displaystyle\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[\\left|\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle\\right|\\right]\\leq\\mathcal{O}\\left(B_{x}(\\Lambda^{\\star})^{\\bar{L}}\\right),$ (43)"},{"child_ids":["A2.E44"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx117","tag":"table","text":"$\\displaystyle\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\Big[\\big(\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle\\big)^{2}\\Big]\\leq\\mathcal{O}\\left(B_{x}^{2}\\mu_{\\Lambda,2}^{\\star}\\right),$ (44)"},{"child_ids":["A2.SS3.p3.1","A2.SS3.p3.1.1","A2.EGx114","A2.E42","A2.SS3.p3.2","A2.SS3.p3.2.1","footnote4","A2.EGx115","A2.Ex82","A2.SS3.p3.3","A2.SS3.p3.3.1","A2.EGx116","A2.E43","A2.SS3.p3.4","A2.SS3.p3.4.1","A2.EGx117","A2.E44","A2.SS3.p3.5","A2.SS3.p3.5.1"],"classes":["ltx_para","ltx_noindent"],"id":"A2.SS3.p3","tag":"div","text":"Next, for the ICL loss, we have $\\displaystyle\\begin{split}&L_{\\textsf{ICL}}(\\boldsymbol{\\theta})\\\\ &=\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[\\left(\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-y_{n+1}\\right)^{2}\\right]\\\\ &=\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[\\left(\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle+\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle-y_{n+1}\\right)^{2}\\right]\\\\ &=\\mathbb{E}_{\\pi}\\bigg\\{\\mathbb{E}_{\\mathcal{P}}\\Big[\\left(\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle\\right)^{2}\\Big]+\\mathbb{E}_{\\mathcal{P}}\\Big[\\left(\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle-y_{n+1}\\right)^{2}\\Big]\\\\ &\\quad\\quad+2\\mathbb{E}_{\\mathcal{P}}\\Big[\\left(\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle\\right)\\left(\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle-y_{n+1}\\right)\\Big]\\bigg\\}\\\\ &\\leq\\mathbb{E}_{\\pi}\\bigg\\{\\mathbb{E}_{\\mathcal{P}}\\Big[\\left(\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle\\right)^{2}\\Big]+\\mathbb{E}_{\\mathcal{P}}\\Big[\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle^{2}\\Big]+\\mathbb{E}_{\\mathcal{P}}\\Big[\\big(\\langle\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle-y_{n+1}\\big)^{2}\\Big]\\\\ &\\quad\\quad+2\\mathbb{E}_{\\mathcal{P}}\\Big[\\left|\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle\\right|\\Big]\\mathbb{E}_{\\mathcal{P}}\\Big[\\left|\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle-y_{n+1}\\right|\\Big]\\bigg\\}\\\\ &\\leq\\mathbb{E}_{\\pi}\\bigg\\{\\mathbb{E}_{\\mathcal{P}}\\Big[\\Big(\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle\\Big)^{2}\\Big]+\\mathbb{E}_{\\mathcal{P}}\\Big[\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle^{2}\\Big]+\\mathbb{E}_{\\mathcal{P}}\\Big[\\big(\\langle\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle-y_{n+1}\\big)^{2}\\Big]\\\\ &\\quad\\quad+2\\mathbb{E}_{\\mathcal{P}}\\Big[\\left|\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle\\right|\\Big]\\left(\\mathbb{E}_{\\mathcal{P}}\\left[\\big|\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle\\big|\\right]+\\mathbb{E}_{\\mathcal{P}}\\Big[\\big|\\langle\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle-y_{n+1}\\big|\\Big]\\right)\\bigg\\}.\\end{split}$ (42) From Corollary 3.1 , we know that there exists a $L=2\\bar{L}+1$ -layer attention-only transformer model $\\boldsymbol{\\theta}$ , with $M=2(p+1)$ heads, and embedding dimension $D=qp+3p+q+3$ , such that for any $\\boldsymbol{H}$ , given any learning rates $\\alpha,\\eta$ and $\\Lambda$ as defined in (9 ), the following holds4 4 4 The clipping bound on $\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}$ can be matched by adjusting the clipping threshold on the last layer of $\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}$ . : $\\displaystyle\\left|\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle\\right|\\leq\\mathcal{O}\\left(B_{x}\\Lambda^{\\bar{L}}\\right).$ Denote $\\Lambda^{\\star}:=\\underset{\\alpha,\\eta}{\\min}\\;\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[\\Lambda|\\boldsymbol{H},\\alpha,\\eta\\right]$ , then under $\\alpha^{\\star},\\eta^{\\star}$ , we have: $\\displaystyle\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[\\left|\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle\\right|\\right]\\leq\\mathcal{O}\\left(B_{x}(\\Lambda^{\\star})^{\\bar{L}}\\right),$ (43) and $\\displaystyle\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\Big[\\big(\\widetilde{\\textsf{TF}}_{\\boldsymbol{\\theta}}(\\boldsymbol{H})-\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}),\\boldsymbol{x}_{n+1}\\rangle\\big)^{2}\\Big]\\leq\\mathcal{O}\\left(B_{x}^{2}\\mu_{\\Lambda,2}^{\\star}\\right),$ (44) where $\\mu_{\\Lambda,2}^{\\star}:=\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[\\Lambda^{2\\bar{L}}|\\boldsymbol{H},\\alpha^{\\star},\\eta^{\\star}\\right]$ is close to 0."},{"child_ids":["A2.E45"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx118","tag":"table","text":"$\\displaystyle\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\Big[\\big|\\langle\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle-y_{n+1}\\big|\\Big]$ $\\displaystyle\\leq\\mathbb{E}_{\\pi}\\left[\\sqrt{\\mathbb{E}_{\\mathcal{P}}\\left(\\epsilon_{n+1}^{2}\\right)}\\right]=\\mathbb{E}_{\\pi}[\\sigma_{\\epsilon}]\\leq\\tilde{\\sigma}_{\\epsilon}.$ (45)"},{"child_ids":["A2.E46"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx119","tag":"table","text":"$\\displaystyle\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle^{2}\\right]\\leq\\mathcal{O}\\left(B_{x}^{2}\\Big(\\frac{C_{z,x}^{2}q\\tilde{\\sigma}^{2}}{n}+\\xi B_{\\beta}^{2}\\Big)\\right).$ (46)"},{"child_ids":["A2.E47"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx120","tag":"table","text":"$\\displaystyle\\begin{split}\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[\\big|\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle\\big|\\right]&\\leq\\sqrt{\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle^{2}\\right]}\\\\ &\\leq\\mathcal{O}\\left(B_{x}\\sqrt{\\frac{C_{z,x}^{2}q\\tilde{\\sigma}^{2}}{n}+\\xi B_{\\beta}^{2}}\\right).\\end{split}$ (47)"},{"child_ids":["A2.E48"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A2.EGx121","tag":"table","text":"$\\displaystyle\\begin{split}&L_{\\textsf{ICL}}(\\boldsymbol{\\theta})-\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[(y_{n+1}-\\langle\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle)^{2}\\right]\\\\ &\\leq\\mathcal{O}\\left(B_{x}^{2}\\Big(\\mu_{\\Lambda,2}^{\\star}+(\\Lambda^{\\star})^{\\bar{L}}\\sqrt{\\frac{C_{z,x}^{2}q\\tilde{\\sigma}^{2}}{n}+\\xi B_{\\beta}^{2}}+\\frac{C_{z,x}^{2}q\\tilde{\\sigma}^{2}}{n}+\\xi B_{\\beta}^{2}\\Big)+B_{x}(\\Lambda^{\\star})^{\\bar{L}}\\tilde{\\sigma}_{\\epsilon}\\right).\\\\ &\\leq\\mathcal{O}\\left((\\Lambda^{\\star})^{\\bar{L}}\\Big(B_{x}^{2}\\sqrt{\\frac{C_{z,x}^{2}q\\tilde{\\sigma}^{2}}{n}+\\xi B_{\\beta}^{2}}+B_{x}\\tilde{\\sigma}_{\\epsilon}\\Big)+B_{x}^{2}\\Big(\\frac{C_{z,x}^{2}q\\tilde{\\sigma}^{2}}{n}+\\xi B_{\\beta}^{2}+\\mu_{\\Lambda,2}^{\\star}\\Big)\\right).\\end{split}$ (48)"},{"child_ids":["A2.SS3.p4.1","A2.SS3.p4.1.1","A2.EGx118","A2.E45","A2.SS3.p4.2","A2.SS3.p4.2.1","A2.EGx119","A2.E46","A2.SS3.p4.3","A2.SS3.p4.3.1","A2.EGx120","A2.E47","A2.SS3.p4.4","A2.SS3.p4.4.1","A2.EGx121","A2.E48"],"classes":["ltx_para","ltx_noindent"],"id":"A2.SS3.p4","tag":"div","text":"With conidition (14 ), from Cauchy-Schwarz inequality, we have: $\\displaystyle\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\Big[\\big|\\langle\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle-y_{n+1}\\big|\\Big]$ $\\displaystyle\\leq\\mathbb{E}_{\\pi}\\left[\\sqrt{\\mathbb{E}_{\\mathcal{P}}\\left(\\epsilon_{n+1}^{2}\\right)}\\right]=\\mathbb{E}_{\\pi}[\\sigma_{\\epsilon}]\\leq\\tilde{\\sigma}_{\\epsilon}.$ (45) Also, from (41 ), we have: $\\displaystyle\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle^{2}\\right]\\leq\\mathcal{O}\\left(B_{x}^{2}\\Big(\\frac{C_{z,x}^{2}q\\tilde{\\sigma}^{2}}{n}+\\xi B_{\\beta}^{2}\\Big)\\right).$ (46) Further, $\\displaystyle\\begin{split}\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[\\big|\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle\\big|\\right]&\\leq\\sqrt{\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[\\langle\\textsf{clip}_{B_{\\beta}}(\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}})-\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle^{2}\\right]}\\\\ &\\leq\\mathcal{O}\\left(B_{x}\\sqrt{\\frac{C_{z,x}^{2}q\\tilde{\\sigma}^{2}}{n}+\\xi B_{\\beta}^{2}}\\right).\\end{split}$ (47) Finally, with (43 )(44 )(45 )(46 )(47 ), rearranging the terms in (42 ), we have: $\\displaystyle\\begin{split}&L_{\\textsf{ICL}}(\\boldsymbol{\\theta})-\\mathbb{E}_{\\pi}\\mathbb{E}_{\\mathcal{P}}\\left[(y_{n+1}-\\langle\\boldsymbol{\\beta},\\boldsymbol{x}_{n+1}\\rangle)^{2}\\right]\\\\ &\\leq\\mathcal{O}\\left(B_{x}^{2}\\Big(\\mu_{\\Lambda,2}^{\\star}+(\\Lambda^{\\star})^{\\bar{L}}\\sqrt{\\frac{C_{z,x}^{2}q\\tilde{\\sigma}^{2}}{n}+\\xi B_{\\beta}^{2}}+\\frac{C_{z,x}^{2}q\\tilde{\\sigma}^{2}}{n}+\\xi B_{\\beta}^{2}\\Big)+B_{x}(\\Lambda^{\\star})^{\\bar{L}}\\tilde{\\sigma}_{\\epsilon}\\right).\\\\ &\\leq\\mathcal{O}\\left((\\Lambda^{\\star})^{\\bar{L}}\\Big(B_{x}^{2}\\sqrt{\\frac{C_{z,x}^{2}q\\tilde{\\sigma}^{2}}{n}+\\xi B_{\\beta}^{2}}+B_{x}\\tilde{\\sigma}_{\\epsilon}\\Big)+B_{x}^{2}\\Big(\\frac{C_{z,x}^{2}q\\tilde{\\sigma}^{2}}{n}+\\xi B_{\\beta}^{2}+\\mu_{\\Lambda,2}^{\\star}\\Big)\\right).\\end{split}$ (48)"},{"child_ids":["A2.SS3.p5.1","A2.SS3.p5.1.1"],"classes":["ltx_para"],"id":"A2.SS3.p5","tag":"div","text":"Thus combining Lemma B.2 with (48 ) completes the proof. ∎"},{"child_ids":["A3.p1.1"],"classes":["ltx_para","ltx_noindent"],"id":"A3.p1","tag":"div","text":"For all experiments in this section, to be consistent with our main experiment in Section 4 , we generate $n=50$ training samples with $p=5,q=10$ , following the data generating process described in Algorithm 1 . The task parameters $\\boldsymbol{\\Theta},\\boldsymbol{\\beta},\\boldsymbol{\\Phi},\\boldsymbol{\\phi}$ are sampled from standard Gaussian distribution, the covariance matrices $\\boldsymbol{\\Sigma}_{z},\\boldsymbol{\\Sigma}_{u},\\boldsymbol{\\Sigma}_{\\omega}$ are set to be identity matrices, and the noise level $\\sigma_{\\epsilon}$ is set to 1."},{"child_ids":["A3.SS1.p1.1"],"classes":["ltx_para","ltx_noindent"],"id":"A3.SS1.p1","tag":"div","text":"In this section, we aim to provide a better understanding of the values of $\\lambda_{z},\\lambda_{\\tilde{x}}$ and $\\delta_{z\\epsilon_{2}}$ required to satisfy condition (3 )."},{"child_ids":["A3.Ex83"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A3.EGx122","tag":"table","text":"$\\displaystyle\\mathbb{P}\\left(\\lambda_{\\min}\\left(\\frac{\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}}{n}\\right)\\leq\\left(1-\\sqrt{\\frac{q}{n}}-\\frac{n}{n-q}\\varepsilon\\right)^{2}\\right)\\leq\\frac{C}{1-\\sqrt{q/n}}\\exp\\left(-c^{\\prime}q\\varepsilon^{3/2}\\right).$"},{"child_ids":["A3.SS1.p2.1","A3.EGx122","A3.Ex83","A3.SS1.p2.2"],"classes":["ltx_para","ltx_noindent"],"id":"A3.SS1.p2","tag":"div","text":"We first investigate $\\lambda_{z}$ . According to Rudelson and Vershynin [2010] , given that random matrix $\\boldsymbol{Z}$ has independent sub-Gaussian entries, one can show that $\\displaystyle\\mathbb{P}\\left(\\lambda_{\\min}\\left(\\frac{\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}}{n}\\right)\\leq\\left(1-\\sqrt{\\frac{q}{n}}-\\frac{n}{n-q}\\varepsilon\\right)^{2}\\right)\\leq\\frac{C}{1-\\sqrt{q/n}}\\exp\\left(-c^{\\prime}q\\varepsilon^{3/2}\\right).$ This inequality implies that setting $\\lambda_{z}$ slightly lower than $(1-\\sqrt{\\frac{q}{n}})^{2}$ is sufficient to ensure a small tail probability."},{"child_ids":["A3.Ex84"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A3.EGx123","tag":"table","text":"$\\displaystyle\\begin{split}\\mathbb{P}\\left(\\left\\|\\frac{\\boldsymbol{Z}^{\\top}\\boldsymbol{\\mathcal{E}}_{2}}{n}\\right\\|\\geq\\varepsilon\\right)&\\leq(q+p)\\exp\\left(-\\frac{n^{2}\\varepsilon^{2}/2}{\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{2}})+B_{z}B_{\\epsilon_{2}}n\\varepsilon/3}\\right)\\\\ \\end{split}$"},{"child_ids":["A3.SS1.p3.1","A3.EGx123","A3.Ex84","A3.SS1.p3.2"],"classes":["ltx_para","ltx_noindent"],"id":"A3.SS1.p3","tag":"div","text":"For $\\delta_{z\\epsilon_{2}}$ , consider the case when $\\boldsymbol{z}$ and $\\boldsymbol{\\epsilon}_{2}$ are uncorrelated (i.e, $\\mathbb{E}[\\boldsymbol{z}\\boldsymbol{\\epsilon}_{2}^{\\top}]=\\boldsymbol{0}$ ), and both $\\boldsymbol{z}$ and $\\boldsymbol{\\epsilon}_{2}$ are almost surely bounded by $B_{z}$ and $B_{\\epsilon_{2}}$ , respectively. Applying the matrix Bernstein inequality (see Lemma A.1 ) directly yields: $\\displaystyle\\begin{split}\\mathbb{P}\\left(\\left\\|\\frac{\\boldsymbol{Z}^{\\top}\\boldsymbol{\\mathcal{E}}_{2}}{n}\\right\\|\\geq\\varepsilon\\right)&\\leq(q+p)\\exp\\left(-\\frac{n^{2}\\varepsilon^{2}/2}{\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{2}})+B_{z}B_{\\epsilon_{2}}n\\varepsilon/3}\\right)\\\\ \\end{split}$ where $\\nu(\\boldsymbol{\\Omega}_{z\\epsilon_{2}})$ increases on the order of $\\mathcal{O}(n)$ . Thus, the tail probability decreases sharply at a rate of $\\mathcal{O}\\left(\\exp(-n)\\right)$ . For the case where $\\mathbb{E}[\\boldsymbol{z}\\boldsymbol{\\epsilon}_{2}^{\\top}]\\neq\\boldsymbol{0}$ , a similar conclusion can be reached by applying the Bernstein inequality on the cetered random matrix $\\frac{\\boldsymbol{Z}^{\\top}\\boldsymbol{\\mathcal{E}}_{2}}{n}-\\mathbb{E}[\\boldsymbol{z}\\boldsymbol{\\epsilon}_{2}^{\\top}]$ ."},{"child_ids":["A3.SS1.p4.1"],"classes":["ltx_para","ltx_noindent"],"id":"A3.SS1.p4","tag":"div","text":"To validate $\\lambda_{\\tilde{x}}$ , we note that the entries of $\\frac{\\boldsymbol{X}^{\\top}\\boldsymbol{P}_{Z}\\boldsymbol{X}}{n}$ are not independent, making it challenging to derive a non-asymptotic bound. However, it is known that $\\lambda_{\\min}\\left(\\frac{\\boldsymbol{X}^{\\top}\\boldsymbol{X}}{n}\\right)$ can be lower bounded with high probability. Since $\\boldsymbol{z}$ and $\\boldsymbol{x}$ are correlated and $\\textsf{rank}(\\boldsymbol{Z})>\\textsf{rank}(\\boldsymbol{X})$ , projecting $\\boldsymbol{X}$ onto the column space of $\\boldsymbol{Z}$ should preserve the eigenproperties of the sample covariance matrix (i.e. the minimal spread along any dimension should not decrease significantly towards 0)."},{"child_ids":["A3.SS1.p5.1"],"classes":["ltx_para","ltx_noindent"],"id":"A3.SS1.p5","tag":"div","text":"To further verify our statements, we conduct 10000 experiments and record the values of $\\lambda_{\\min}(\\frac{\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}}{n}),\\lambda_{\\min}(\\frac{\\boldsymbol{X}^{\\top}\\boldsymbol{P}_{Z}\\boldsymbol{X}}{n})$ , and $\\|\\frac{\\boldsymbol{Z}^{\\top}\\boldsymbol{\\mathcal{E}}_{2}}{n}\\|$ . The histograms shown in Figure 3 indicate that mild choices on $\\lambda_{z},\\lambda_{\\tilde{x}}$ and $\\delta_{z\\epsilon_{2}}$ are sufficient to satisfy the sample condition (3 ). Specifically, we have $\\xi=0.01,\\lambda_{z}=0.2137,\\lambda_{\\tilde{x}}=0.2011,$ and $\\delta_{z\\epsilon_{2}}=3.3617$ as empirical guidelines."},{"child_ids":["A3.Ex85"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A3.EGx124","tag":"table","text":"$\\displaystyle\\frac{2}{\\sigma_{\\max}^{2}(\\boldsymbol{Z}\\hat{\\boldsymbol{\\Theta}})}=0.0016,\\frac{2}{\\sigma_{\\max}^{2}(\\boldsymbol{Z})}=0.0212.$"},{"child_ids":["A3.SS2.p1.1","A3.SS2.p1.1.1","A3.EGx124","A3.Ex85"],"classes":["ltx_para","ltx_noindent"],"id":"A3.SS2.p1","tag":"div","text":"We use the GD-based 2SLS method (8 ) to estimate the causal effect $\\boldsymbol{\\beta}$ . For the simulated data, we calculate the following metrics: $\\displaystyle\\frac{2}{\\sigma_{\\max}^{2}(\\boldsymbol{Z}\\hat{\\boldsymbol{\\Theta}})}=0.0016,\\frac{2}{\\sigma_{\\max}^{2}(\\boldsymbol{Z})}=0.0212.$"},{"child_ids":["A3.Ex86","A3.Ex87"],"classes":["ltx_equationgroup","ltx_eqn_align","ltx_eqn_table"],"id":"A3.EGx125","tag":"table","text":"$\\displaystyle\\gamma(\\alpha)$ $\\displaystyle:=\\rho\\left(\\boldsymbol{I}-\\alpha\\hat{\\boldsymbol{\\Theta}}^{\\top}\\boldsymbol{Z}^{\\top}\\boldsymbol{Z\\hat{\\Theta}}\\right),$ $\\displaystyle\\kappa(\\eta)$ $\\displaystyle:=\\rho\\left(\\boldsymbol{I}-\\eta\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}\\right).$"},{"child_ids":["A3.SS2.p2.1","A3.EGx125","A3.Ex86","A3.Ex87"],"classes":["ltx_para","ltx_noindent"],"id":"A3.SS2.p2","tag":"div","text":"By Theorem 3.1 , the gradient descent converges when $\\alpha\\in(0,0.0016)$ and $\\eta\\in(0,0.0212)$ . The overall convergence rate is determined by $\\Lambda:=\\max\\{\\gamma(\\alpha),\\kappa(\\eta)\\}$ , where $\\displaystyle\\gamma(\\alpha)$ $\\displaystyle:=\\rho\\left(\\boldsymbol{I}-\\alpha\\hat{\\boldsymbol{\\Theta}}^{\\top}\\boldsymbol{Z}^{\\top}\\boldsymbol{Z\\hat{\\Theta}}\\right),$ $\\displaystyle\\kappa(\\eta)$ $\\displaystyle:=\\rho\\left(\\boldsymbol{I}-\\eta\\boldsymbol{Z}^{\\top}\\boldsymbol{Z}\\right).$"},{"child_ids":["A3.SS2.p3.1","A3.SS2.p3.1.1"],"classes":["ltx_para","ltx_noindent"],"id":"A3.SS2.p3","tag":"div","text":"We first set $\\alpha=0.0012$ and vary $\\eta$ . The corresponding convergence rates are determined by $\\Lambda=\\max(0.87,\\kappa(\\eta))$ . Next, we set $\\eta=0.01$ and vary $\\alpha$ . The corresponding convergence curves are determined by $\\Lambda=\\max(\\gamma(\\alpha),0.82)$ . We compare the estimates $\\hat{\\boldsymbol{\\beta}}^{(t)}$ with the 2SLS estimate $\\hat{\\boldsymbol{\\beta}}_{\\textsf{2SLS}}$ as the iteration proceeds. The convergence results are shown in Figure 4 ."},{"child_ids":["A3.SS2.p4.1"],"classes":["ltx_para","ltx_noindent"],"id":"A3.SS2.p4","tag":"div","text":"The results in Figure 4 are consistent with our theoretical analysis in Theorem 3.1 . It is worth noting that in Figure 4(a) , when $\\eta$ is relatively large (or small), the convergence curves exhibit some suiggly patterns. This is due to the innerloop updates (8a ) are converging faster (or slower) than the outer loop updates (8b ). However, the overall convergence rate is still determined by $\\Lambda$ . This pattern doesn’t appear in Figure 4(b) as we set $\\eta$ to be a moderate value, which ensures that the inner loop and outer loop converge synchronously."},{"child_ids":["A3.SS2.p5.1"],"classes":["ltx_para","ltx_noindent"],"id":"A3.SS2.p5","tag":"div","text":"Next, we show the bias of the GD estimator. For better convergence, we set $\\alpha^{\\star}=\\frac{1}{\\sigma_{\\max}^{2}(\\boldsymbol{Z\\hat{\\Theta}})}$ and $\\eta^{\\star}=\\frac{1}{\\sigma_{\\max}^{2}(\\boldsymbol{Z})}$ . We compare the biases of the GD estimator with $n=50,100,150$ in-context samples. The results are shown in Figure 5 ."}]}

